function icon(string $name, string $class = 'h-4 w-4', float $stroke = 2): string
{
    $path = UI_ICONS[$name] ?? UI_ICONS['info'];
    return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" '
        . 'stroke-width="' . e((string)$stroke) . '" stroke-linecap="round" stroke-linejoin="round" '
        . 'class="' . e($class) . '" aria-hidden="true" focusable="false">' . $path . '</svg>';
}
